operations.alarm-checklist-release-ruby:
/usr/bin/printf '%b' 'set -eu
[ "$(/usr/bin/uname -s)" = Darwin ] || { echo '"'"'macOSが必要です。'"'"' >&2; exit 1; }
case $(/usr/bin/uname -m) in
  arm64) prefix=/opt/homebrew ;;
  x86_64) prefix=/usr/local ;;
  *) echo '"'"'対応するHomebrewの場所を確認できません。'"'"' >&2; exit 1 ;;
esac
brew="$prefix/bin/brew"
[ -x "$brew" ] || { echo '"'"'既存のHomebrewが見つかりません。'"'"' >&2; exit 1; }
brew_ruby() {
  /usr/bin/env -i HOME="$HOME" PATH="$prefix/bin:/usr/bin:/bin:/usr/sbin:/sbin" \
    HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_NO_INSTALL_UPGRADE=1 HOMEBREW_NO_INSTALL_CLEANUP=1 \
    HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1 HOMEBREW_NO_SUDO=1 \
    "$brew" "$@"
}
ruby_bin="$prefix/opt/ruby@3.3/bin"
if [ ! -x "$ruby_bin/ruby" ]; then
  brew_ruby install --no-ask --force-bottle --formula ruby@3.3 </dev/null ||
    { echo '"'"'配信用のRuby 3.3を用意できませんでした。'"'"' >&2; exit 1; }
fi
"$ruby_bin/ruby" --version
[ -x "$ruby_bin/bundle" ] || { echo '"'"'Ruby 3.3のBundlerが見つかりません。'"'"' >&2; exit 1; }
PATH="$ruby_bin:/usr/bin:/bin:/usr/sbin:/sbin" "$ruby_bin/bundle" --version
printf '"'"'alarm-checklistの配信用RubyとBundlerを確認しました。PATHに追加するディレクトリ: %s\n'"'"' "$ruby_bin"
' | /bin/sh

operations.alarm-checklist-native-log:
/usr/bin/printf '%b' 'import json
import os
import re
import stat
from pathlib import Path

root = Path.home() / "Library/Caches/issue-desk/apple/macbook-pro-test/control/state/requests"
if not root.is_dir() or root.resolve() != root:
    raise SystemExit("MacBook Proの検証結果ディレクトリを確認できません。")

rows = []
for path in root.iterdir():
    if not re.fullmatch(r"[0-9]{1,16}-[a-f0-9]{8}\.json", path.name):
        continue
    try:
        with os.fdopen(os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK), "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_size > 65536:
                continue
            row = json.loads(stream.read(65537))
        request, result = row["request"], row["result"]
        if request["kind"] != "native_test" or request["repo"] != "mofua-suki/alarm-checklist":
            continue
        head = result["head"]
        disposition = result["status"]
        if not re.fullmatch(r"[a-f0-9]{40}", head) or disposition not in ("failed", "unrunnable", "interrupted"):
            continue
        rows.append((info.st_mtime, path.stem, head, disposition, result["message"]))
    except (OSError, UnicodeError, ValueError, TypeError, KeyError):
        continue

secret = re.compile(r"authorization|bearer|credential|password|secret|token|access[ _-]?key|api[ _-]?key|private[ _-]?key|\.p8\b|id[kh]_", re.I)
for _, record, head, disposition, message in sorted(rows, reverse=True)[:4]:
    print(f"{record} head={head} status={disposition}")
    if not isinstance(message, str):
        continue
    for line in message.splitlines():
        if secret.search(line):
            continue
        line = re.sub(r"https?://[^\s]+", "[URL]", line)
        line = "".join(character for character in line if character.isprintable())
        if line:
            print(line[:1000])
if not rows:
    print("alarm-checklistの保存済み検証失敗はありません。")
' | /usr/bin/python3 -
